# ---------------------------------------------------------------- S95
S(95, 'Revenue, costs, profit, and break-even', 'Calculate profit and the break-even point for a small business',
  main=[
    q('Dev sells custom T-shirts for $20 each. In May he sells 80 shirts. His costs are $600 for a heat press (fixed) and $8 per shirt for blanks and ink. What is his profit?', '$360',
      [('$1,600', 'Gives revenue, not profit'), ('$1,000', 'Subtracts only the fixed cost'), ('$960', 'Subtracts only the per-shirt costs')],
      intro='Revenue = price × number sold. Costs include fixed costs (the same no matter how many you sell, such as equipment) and variable costs (per item). Profit = revenue − total costs.',
      fb='Revenue $1,600; costs $600 + 80 × $8 = $1,240; profit $360.', calc=360, sub='Profit'),
    q('Dev\'s fixed cost is $600; each shirt sells for $20 and costs $8 to make. How many shirts must he sell to break even?', '50',
      [('30', 'Divides by the $20 price'), ('75', 'Divides by the $8 cost'), ('600', 'Uses the fixed cost as the count')],
      intro='Each shirt adds price − variable cost toward fixed costs (the contribution per unit). Break-even units = fixed costs ÷ (price − variable cost).',
      fb='$20 − $8 = $12 per shirt; $600 ÷ $12 = 50 shirts.', calc=50, sub='Break-even'),
    q('Which is a variable cost for Dev\'s T-shirt business?', 'Blank shirts',
      [('The heat press he bought once', 'Fixed cost'), ('A yearly business registration fee', 'Fixed cost'), ('Monthly website hosting', 'Fixed cost')],
      intro='Variable costs rise with each item made; fixed costs stay the same as sales change.',
      fb='Each shirt needs a blank, so blanks are variable.', sub='Fixed vs variable'),
    q('Dev\'s revenue is $2,000 and his profit is $500. What is his profit margin?', '25%',
      [('4%', 'Divides revenue by profit'), ('40%', 'Divides by $1,250'), ('75%', 'Gives the share that went to costs')],
      intro='Profit margin = profit ÷ revenue × 100. It shows how much of each sales dollar is kept.',
      fb='$500 ÷ $2,000 = 25%.', calc=25, sub='Profit margin'),
    q('Before quitting a job to run a business full time, what should Dev check first?', 'Whether profits cover his living costs',
      [('Whether he has sold out of shirts once', 'One sale is not steady profit'), ('Whether revenue is higher than last month', 'Revenue is not profit'), ('Whether he can buy more equipment on credit', 'Adds debt')],
      fb='Profit, not revenue, must cover personal expenses, taxes, and savings.', sub='Planning'),
  ],
  back=[
    concept('Revenue and costs', 'Profit and break-even rest on separating revenue from costs.', [
      q('Revenue means…', 'Money received from sales',
        [('Money left after paying costs', 'Profit'), ('Money borrowed to start', 'Debt'), ('Money paid to suppliers', 'Costs')],
        fb='Revenue is total sales.', sub='Revenue'),
      q('30 items sold at $15 each bring in…', '$450',
        [('$45', 'Drops a zero'), ('$2', 'Divides'), ('$4,500', 'Adds a zero')],
        fb='30 × $15 = $450.', calc=450, sub='Revenue'),
      q('Revenue $450, costs $300. Profit is…', '$150',
        [('$750', 'Adds'), ('$300', 'Gives costs'), ('-$150', 'Subtracts in the wrong order')],
        fb='$450 − $300 = $150.', calc=150, sub='Profit'),
      q('What is a loss?', 'Costs greater than revenue',
        [('Revenue greater than costs', 'Profit'), ('Selling more items', 'Not a loss'), ('A fixed cost', 'Not a result')],
        fb='A loss happens when costs exceed revenue.', sub='Loss'),
      q('Which cost stays the same whether Dev sells 10 or 100 shirts?', 'His monthly booth rent',
        [('Ink used per shirt', 'Variable'), ('Shipping costs for each order', 'Variable'), ('Blank shirts', 'Variable')],
        fb='Rent is fixed.', sub='Fixed costs'),
    ]),
    math('Write and solve systems of linear equations for real-world problems', 'Break-even is where the revenue line meets the cost line.', 'grade_8', 22),
    math('Create linear equations and inequalities in one variable', 'Profit goals lead to equations such as 12x − 600 = 360.', 'algebra_1', 20),
  ],
  go=[
    deeper('Using break-even to plan', [
      q('Dev wants $480 profit a month. Fixed costs are $600 and each shirt adds $12 of contribution. How many shirts must he sell?', '90',
        [('40', 'Ignores the fixed costs'), ('50', 'Gives break-even'), ('24', 'Divides by $20')],
        intro='Units for a profit goal = (fixed costs + profit goal) ÷ contribution per unit.',
        fb='($600 + $480) ÷ $12 = 90 shirts.', calc=90, sub='Profit goals'),
      q('If Dev raises the price to $24 (cost still $8; fixed $600), what is the new break-even point?', '37.5, so 38 shirts',
        [('50 shirts', 'Uses the old price'), ('25 shirts', 'Divides by $24'), ('75 shirts, using $8', 'Divides by $8')],
        intro='A higher price raises the contribution per unit, so fewer sales are needed, if customers still buy.',
        fb='$24 − $8 = $16; $600 ÷ $16 = 37.5, so 38 shirts.', calc=37.5, sub='Price changes'),
      q('Cost: C = 600 + 8x. Revenue: R = 20x. Where do the two lines cross?', 'At x = 50',
        [('At x = 30', 'Uses 600 ÷ 20'), ('At x = 75', 'Uses 600 ÷ 8'), ('At x = 600', 'Uses the intercept')],
        fb='20x = 600 + 8x gives 12x = 600, x = 50.', calc=50, sub='Graphing break-even'),
      q('Dev sells shirts for $20 each; each costs $8 to make. Above the break-even point, how much profit does each extra shirt add?', '$12',
        [('$20', 'Gives the price'), ('$8', 'Gives the cost'), ('$28', 'Adds price and cost')],
        intro='Once fixed costs are covered, each extra sale adds its contribution: price − variable cost.',
        fb='Each shirt beyond break-even adds $20 − $8 = $12.', calc=12, sub='Contribution'),
      q('A supplier raises blanks from $8 to $10. With a $20 price and $600 fixed costs, what is the new break-even?', '60 shirts',
        [('50 shirts', 'Uses the old cost'), ('30 shirts', 'Divides by $20'), ('20 shirts', 'Divides by $30')],
        fb='$20 − $10 = $10; $600 ÷ $10 = 60.', calc=60, sub='Cost changes'),
    ]),
    deeper('Cash flow and records', [
      q('In June, Dev collects $900 in cash from customers and pays $1,100 in cash for supplies for a big July order. He has no other cash coming in or going out. What is June\'s net cash flow?', '-$200',
        [('$200', 'Ignores the sign'), ('$2,000', 'Adds'), ('$900', 'Counts only money in')],
        intro='Cash flow = money actually received − money actually paid in a period. Sales made on credit are not cash until collected (they are accounts receivable). A profitable business can still run short of cash when it pays before it gets paid.',
        fb='$900 − $1,100 = −$200.', calc=-200, sub='Cash flow'),
      q('Why should Dev keep business money in a separate account?', 'It makes records and taxes clearer',
        [('Banks forbid personal accounts for business', 'Not always'), ('It doubles interest', 'Confuses accounts with returns'), ('It removes the need for taxes', 'Misunderstands taxes')],
        fb='Separate accounts make tracking income and expenses easier.', sub='Separate accounts', how=True),
      q('A customer owes Dev $250 and pays 30 days later. What is this unpaid amount called?', 'Accounts receivable',
        [('Accounts payable due', 'Money Dev owes'), ('Fixed cost', 'A type of cost'), ('Gross profit', 'A result')],
        fb='Money owed to the business is accounts receivable.', sub='Receivables'),
      q('Dev keeps $500 in a business reserve. Costs are $300 a month with no sales. How many months could he cover?', 'About 1.7 months',
        [('About 3 months', 'Divides $900 by $300'), ('About 0.6 months', 'Divides the wrong way'), ('About 800 months', 'Adds the amounts')],
        fb='$500 ÷ $300 ≈ 1.7 months.', calc=500/300, sub='Reserves'),
      q('Which record best supports a business expense at tax time?', 'A receipt showing what was bought and when',
        [('A memory of the purchase', 'Not documentation'), ('A note in his phone with the total', 'Lacks proof'), ('A bank account balance alone', 'Lacks detail')],
        fb='Receipts and invoices document expenses.', sub='Recordkeeping', how=True),
    ]),
  ],
  nat=('Earning Income', 'Calculate profit and break-even for a small business and explain the role of fixed and variable costs'), nj=['PB', 'EG'],
  extra=['Finding a break-even point', 'Separating business and personal money'])

